import { test } from "node:test";
import assert from "node:assert/strict";
import { tableView } from "./table-view.mjs";

test("C3 1,000 projects: the first page shows 25 rows", () => {
  const projects = Array.from({ length: 1000 }, (_, i) => ({ name: `Project ${i + 1}` }));
  const view = tableView(projects);
  assert.equal(view.rows.length, 25);
  assert.equal(view.rows[0].name, "Project 1");
});
